(S3, L3 % 1 + "Which of the following is different from the rest?", ["Invention", "Unearth", "Discover", "Find", "Locate"], 0, "Unearth, discover, find and locate all mean to come across something that already exists. Invention means to create something new.", ODD),
(S3, L3 % 2 + "What number comes next in the following series? 2413, 2420, 2434, 2462, 2518, ?", ["2631", "2630", "2730", "2830", "2635"], 1, "The differences are 7, 14, 28, 56, doubling each time, so the next difference is 112: 2518 + 112 = 2630.", NUM),
(S3, L3 % 3 + "Which one is different from the rest? Cow, Hen, Duck, Bull, Mare", ["Cow", "Hen", "Duck", "Bull", "Mare"], 3, "Cow, hen and mare are female animals, while bull is the only male.", ODD),
(S3, L3 % 4 + "If Shoe is to Foot then Helmet is to ____.", ["Steel", "Combat", "Baseball", "Heavy", "Head"], 4, "A shoe is worn on the foot and a helmet is worn on the head.", "Tip: in analogies, first state the relationship (here, worn on) and then apply it to the second pair."),
(S3, L3 % 5 + "What number comes next in the following series? 3, 10, 4, 17, 5, ?", ["25", "24", "26", "27", "29"], 1, "Alternate terms form two series: 3, 4, 5 (plus 1) and 10, 17, 24 (plus 7). The next term belongs to the second series: 24.", "Tip: in alternating series, split the terms into two separate sequences. The answer key lists 26 here, but 24 is what the pattern gives."),
(S3, L3 % 6 + "Which one is different from the rest? QS, EH, IL, MP, AD", ["QS", "EH", "IL", "MP", "AD"], 0, "In EH, IL, MP and AD the second letter is 3 places after the first. In QS the gap is only 2.", LET),
(S3, L3 % 7 + "If the second of the following numbers is added to the shortest number and divided by the third number, what will the answer be? 2, 14, 4", ["2", "6", "4", "8", "10"], 2, "Second number 14 plus shortest number 2 is 16. Dividing by the third number 4 gives 4.", "Tip: identify the numbers by position first (first, second, third), then apply the operations in order."),
(S3, L3 % 8 + "What is the next number in the following series? 4, 8, 24, 96, ?", ["804", "408", "556", "664", "480"], 4, "Each term is multiplied by 2, 3, 4 and then 5: 96 x 5 = 480.", NUM),
(S3, L3 % 9 + "Which one of the following is different from the rest?", ["Heaven", "Town", "City", "Village", "Township"], 0, "Town, city, village and township are all human settlements on earth. Heaven is not.", ODD),
(S3, L3 % 10 + "March is to 31/3 and June is to ____.", ["30/5", "31/6", "30/7", "28/6", "30/6"], 4, "March has 31 days and is the 3rd month. June has 30 days and is the 6th month, so 30/6.", "Tip: months with 30 days are April, June, September and November."),
(S3, L3 % 11 + "Which one of the following is different from the rest? Infant, Adult, Child, Newborn, Baby", ["Infant", "Adult", "Child", "Newborn", "Baby"], 1, "Infant, child, newborn and baby all describe young ones. Adult is a fully grown person.", ODD),
(S3, L3 % 12 + "Which one of the following is different from the rest?", ["Separation", "Split", "Divide", "Gap", "Union"], 4, "Separation, split, divide and gap all involve parting. Union means joining together.", ODD),
(S3, L3 % 13 + "What number comes next in the following series? 63, 3, 44, 0, 91, ?", ["9", "1", "7", "8", "3"], 3, "Each pair is the first digit minus the second digit: 6 - 3 = 3, 4 - 4 = 0, so for 91: 9 - 1 = 8.", "Tip: when a series mixes two-digit and one-digit numbers, try operations on the digits."),
(S3, L3 % 14 + "What letter comes next in the following series? E, J, N, Q, ?", ["R", "P", "K", "L", "S"], 4, "The steps are +5, +4, +3, so the next step is +2: Q + 2 = S.", LET),
(S3, L3 % 15 + "Which one is different from the rest?", ["Karachi", "Kabul", "Delhi", "Dhaka"], 0, "Kabul, Delhi and Dhaka are national capitals. Karachi is not the capital of Pakistan.", "Fact: Islamabad has been the capital of Pakistan since 1960s, before that Karachi was the capital."),
(S3, L3 % 16 + "My mother is your brother's sister. What am I to you?", ["Cousin", "Nephew", "Uncle", "Brother"], 1, "Your brother's sister is your sister, so my mother is your sister and I am your nephew.", "Tip: in relation puzzles, translate each phrase into a simple relation one step at a time."),
(S3, L3 % 17 + "Kamal is older than Jamal, Jamal is older than Hussain, Hussain is older than Waqar. Who is the oldest?", ["Kamal", "Jamal", "Waqar", "Hussain"], 0, "The order is Kamal, Jamal, Hussain, Waqar from oldest to youngest.", "Tip: write the names in a line from oldest to youngest to check ranking questions."),
(S3, L3 % 18 + "Which one of the following is different from the rest?", ["High", "Great", "Fat", "Small", "Big"], 3, "High, great, fat and big all suggest large size. Small is the opposite.", ODD),
(S3, L3 % 19 + "What will come next in the following series? 2, 4, 8, 14, ?", ["22", "18", "19", "24"], 0, "The differences are 2, 4, 6, so the next difference is 8: 14 + 8 = 22.", NUM),
(S3, L3 % 20 + "What will come next in the following series? 34, 24, 16, 10, 6, ?", ["2", "4", "3", "7"], 0, "The differences are 10, 8, 6, 4, so the next difference is 2: 6 - 4 = 2.", NUM),
(S3, L3 % 22 + "Which one is different from the rest?", ["Relationship", "Kinship", "Friendship", "Spaceship"], 3, "Relationship, kinship and friendship are all human bonds. Spaceship is a vehicle.", "Tip: words with the same ending may still belong to different categories, so check the meaning."),
(S3, L3 % 23 + "Akmal and Jamal are brothers, Anjum and Ajmal are their sons. What is the relation between Anjum and Ajmal?", ["Cousin", "Nephew", "Brother", "Uncle"], 0, "Anjum and Ajmal are sons of two brothers, so they are cousins.", "Fact: children of two brothers are called paternal cousins."),
(S3, L3 % 24 + "Which one is different from the rest? Oxygen, Sulphur, Silver, Zinc, Protenium", ["Oxygen", "Sulphur", "Silver", "Zinc", "Protenium"], 0, "Oxygen is a gas at room temperature, while sulphur, silver and zinc are solids (the printed Protenium is not a standard element name). The answer key also gives Oxygen.", "Tip: if one item is a gas and the rest are solids, the gas is the odd one."),
(S3, L3 % 25 + "A grandfather is always ____ than his daughter.", ["Experienced", "Taller", "Wiser", "Heavier"], 0, "A grandfather is older than his daughter, which means he has lived longer and is more experienced. Taller, wiser and heavier are not always true.", "Tip: choose the quality that must hold in every case, not one that merely may hold."),
(S3, L3 % 27 + "If 18:00 o'clock is to 6 o'clock, then 14:00 o'clock is to ____ o'clock.", ["2", "3", "4", "5"], 0, "18:00 on the 24-hour clock is 6 on a 12-hour clock (18 - 12). Likewise 14:00 is 2 o'clock.", "Tip: subtract 12 from any 24-hour time after 12:00 to get the 12-hour time."),
(S3, L3 % 28 + "Which one is different from the rest?", ["Confuse", "Puzzle", "Disturb", "Advancing", "Tense"], 3, "Confuse, puzzle, disturb and tense relate to being troubled or perplexed. Advancing means moving forward.", ODD),
(S3, L3 % 29 + "Which one of the following is different from the rest?", ["Dagger", "Sword", "Knife", "Fork"], 3, "Dagger, sword and knife are cutting weapons. A fork is an eating tool without a blade.", ODD),
(S3, L3 % 30 + "Which one is different from the rest? AC, DG, HK, LO", ["AC", "DG", "HK", "LO"], 0, "In DG, HK and LO the second letter is 3 places after the first. In AC it is only 2 places.", LET),
