(S4, L4 % 1 + "Which comes next in the following series? A, B, C, D, E, ?", ["G", "F", "H", "E"], 1, "These are consecutive letters of the alphabet, so after E comes F.", LET),
(S4, L4 % 2 + "Which number comes next in the following series? 64, 32, 16, 8, ?", ["2", "6", "4", "12"], 2, "Each term is half of the one before: 8 / 2 = 4.", NUM),
(S4, L4 % 3 + "Add the smallest and the largest numbers and divide the total by the third number. The numbers are 3, 6, 15.", ["6", "4", "3", "9"], 2, "Smallest 3 plus largest 15 is 18. The third number is 6, and 18 / 6 = 3.", "Tip: the third number means the third in the printed order, not the third largest."),
(S4, L4 % 4 + "STONE is to HARD as COTTON WOOL is to:", ["White", "Warm", "Soft", "Cheap", "Sponge"], 2, "A stone is characterised by being hard, and cotton wool by being soft.", "Tip: in analogies, name the quality that links the first pair."),
(S4, L4 % 5 + "DEAL is to 7345 as LEAD is to:", ["7435", "5437", "5347", "5734"], 2, "D=7, E=3, A=4, L=5. LEAD is L, E, A, D = 5, 3, 4, 7, which gives 5347.", CODE),
(S4, L4 % 6 + "Tree is to branches as river is to:", ["Delta", "Canals", "Water", "Bank", "Flood"], 1, "Branches spread out from a tree, and canals are channels taken off a river. This matches the answer key (a delta could also be argued).", "Tip: when two options seem close, pick the one that fits the relationship in the first pair most directly."),
(S4, L4 % 7 + "Which one of the following is different from the others?", ["Date", "Calendar", "Year", "Day", "Minute"], 4, "Date, calendar, year and day are all calendar terms. A minute is a small unit of clock time.", ODD),
