(S4, L4 % 10 + "What is the total cost of two pencils at Rs.2 each and one dozen sharpeners at Rs.3 each?", ["Rs.38", "Rs.30", "Rs.40", "Rs.42"], 2, "Pencils cost 2 x 2 = 4. A dozen sharpeners cost 12 x 3 = 36. The total is 40.", "Tip: one dozen means 12 items."),
(S4, L4 % 11 + "If Akram is older than Kamal and Hamid is younger than Kamal but Amjad is older than Hamid, who is the youngest?", ["Akram", "Kamal", "Hamid", "Amjad"], 2, "Hamid is younger than Kamal and Amjad, and Kamal is younger than Akram, so Hamid is the youngest.", "Tip: write the names in a line from oldest to youngest to check ranking questions."),
(S4, L4 % 12 + "Write the letter that is as far from the beginning of the alphabet as D is from the beginning of the word PROUDLY.", ["D", "E", "F", "U"], 1, "In PROUDLY, D is the 5th letter (P, R, O, U, D). The 5th letter of the alphabet is E.", "Tip: count the position in the word first and then use that number in the alphabet."),
(S4, L4 % 13 + "Which letter comes next in the following series? A, D, G, J, M, ?", ["N", "O", "Q", "P"], 3, "The letters go up by 3 each time, so after M comes P.", LET),
