(S5, L5 % 10 + "Ten boxes of oranges weigh 120 kg. Each box when empty weighs 3 kg. What is the actual weight of oranges?", ["80 kg", "30 kg", "90 kg", "50 kg"], 2, "The ten empty boxes weigh 10 x 3 = 30 kg. The oranges weigh 120 - 30 = 90 kg.", "Tip: subtract the packaging weight to get the net weight."),
(S5, L5 % 11 + "If Imran is older than Waseem and Kaleem is younger than Imran, which of the following statements is true?", ["Imran is the oldest", "Waseem is the youngest", "Kaleem is the youngest", "Waseem and Kaleem are of equal age"], 0, "Imran is older than both Waseem and Kaleem, so he is the oldest. The relative ages of Waseem and Kaleem are not known.", "Tip: only accept statements that follow from the facts given."),
(S5, L5 % 12 + "How many letters in the word GENERAL are also found in the word REGULAR?", ["4", "5", "6", "3"], 1, "The letters G, E, R, A and L of GENERAL appear in REGULAR, while N does not. That gives 5 letters.", "Tip: count each distinct letter once unless told to count repeats."),
