(S5, L5 % 18 + "Which letter comes next in the following series? Q, P, O, N, M, ?", ["R", "S", "T", "L"], 3, "The letters go backwards through the alphabet, so after M comes L.", LET),
(S5, L5 % 19 + "If a train covers a distance of 75 km in one hour, how much time will it take to cover 225 km?", ["3 hrs", "4 hrs", "5 hrs", "6 hrs"], 0, "Time = 225 / 75 = 3 hours.", "Tip: time = distance divided by speed."),
(S5, L5 % 20 + "Children eat food because:", ["They like to eat", "They are hungry", "They want to be healthy", "Their parents ask them to eat"], 1, "Hunger is the basic reason children eat.", "Tip: choose the most basic reason."),
(S5, L5 % 21 + "Which letter comes next in the following series? K, I, G, E, C, ?", ["A", "B", "D", "Z"], 0, "The letters go back by 2 each time, so C - 2 = A.", LET),
(S5, L5 % 22 + "A man walked 4 km in 30 minutes and another 11 km in one hour. What was his per hour speed to cover the whole distance?", ["12 km per hour", "8 km per hour", "15 km per hour", "10 km per hour"], 3, "The total distance is 4 + 11 = 15 km and the total time is 1.5 hours. Speed = 15 / 1.5 = 10 km per hour.", "Tip: average speed = total distance divided by total time."),
(S5, L5 % 23 + "It rains because:", ["Farmers need water", "Water becomes cold", "Clouds come in the sky", "Children like to have a shower"], 2, "Rain falls from clouds when the water droplets in them gather and become heavy. This follows the answer key.", "Fact: rain is part of the water cycle of evaporation, condensation and precipitation."),
(S5, L5 % 24 + "Which number comes next? 18, 13, 9, 6, ?", ["5", "4", "3", "2"], 1, "The differences are 5, 4, 3, so the next difference is 2: 6 - 2 = 4.", NUM),
