(S5, L5 % 27 + "Which number comes next? 32, 22, 14, 8, ?", ["2", "4", "6", "1"], 1, "The drops are 10, 8, 6, so the next difference is 4. The terms drop by 10, 8, 6, then 4: 8 - 4 = 4.", NUM),
(S5, L5 % 28 + "All lawyers wear black coats. Aslam wears a black coat, therefore he:", ["Is a lawyer", "Is not a lawyer", "May be a lawyer"], 2, "Others can also wear black coats, so Aslam may or may not be a lawyer.", "Tip: all A are B does not mean all B are A."),
(S5, L5 % 29 + "A train travelled for 30 minutes at a speed of 90 km per hour and for another 50 minutes at a speed of 120 km per hour. How much distance will it cover?", ["120 km", "100 km", "145 km", "135 km"], 2, "In 30 minutes at 90 km per hour it goes 45 km. In 50 minutes at 120 km per hour it goes 100 km. The total is 145 km.", "Tip: convert minutes to hours before multiplying by speed."),
(S5, L5 % 30 + "PREVENT means the same as:", ["Avoid", "Cruel", "Allow", "Stop", "Fear"], 3, "To prevent something is to stop it from happening. The paper key gives Avoid, but Stop is the closest meaning.", "Tip: allow is the opposite of prevent."),
